package com.flippingfriend.companion;
/** Immutable production-equivalent expected-profit evidence. */
final class BuyReplacementExpectedProfitEvaluation {
 private final BuyReplacementUnwindLossEvaluation source; private final double completedProbability; private final double strandedProbability; private final double expectedProfit;
 BuyReplacementExpectedProfitEvaluation(BuyReplacementUnwindLossEvaluation s,double c,double stranded,double profit){source=s;completedProbability=c;strandedProbability=stranded;expectedProfit=profit;}
 int getBuyOffsetIndex(){return source.getBuyOffsetIndex();} double getBuyOffset(){return source.getBuyOffset();} int getBuyPrice(){return source.getBuyPrice();} int getExactRemainderQuantity(){return source.getExactRemainderQuantity();} long getTotalCost(){return source.getTotalCost();} int getSellOffsetIndex(){return source.getSellOffsetIndex();} double getSellOffset(){return source.getSellOffset();} int getSellPrice(){return source.getSellPrice();} long getNetMarginPerItem(){return source.getNetMarginPerItem();} long getTotalNetMargin(){return source.getTotalNetMargin();} double getBuyProbability(){return source.getBuyProbability();} double getSellProbability(){return source.getSellProbability();} double getCompletionProbability(){return source.getCompletionProbability();} double getExpectedSlotHours(){return source.getExpectedSlotHours();} long getTotalUnwindLoss(){return source.getTotalUnwindLoss();} double getCompletedProbability(){return completedProbability;} double getStrandedProbability(){return strandedProbability;} double getExpectedProfit(){return expectedProfit;}
}
